(function(root){
  const labels={maintenance:'일반 유지',weight:'체중 관리',renal:'신장 관리',urinary:'요로 관리',gi:'소화기 관리',lowfat:'저지방 관리',allergy:'식이 이상반응 관리',other:'기타 질환'};
  const n=v=>(v===null||v===undefined||String(v).trim()==='')?NaN:Number(v);
  const rer=kg=>70*Math.pow(kg,.75);
  const within=(v,min,max)=>Number.isFinite(n(v))&&n(v)>=min&&n(v)<=max;
  function kcalPerGram(product){if(!product||!within(product.energy,.001,10000))return null;const e=n(product.energy);switch(product.energyUnit){case 'kg':return e/1000;case '100g':return e/100;case 'g':return e;case 'pack':return within(product.packGrams,1,5000)?e/n(product.packGrams):null;default:return null;}}
  function automaticFactor(p){if(p.goal==='loss')return p.species==='cat'?.8:1;if(p.activity==='low')return p.species==='cat'?1:1.2;return p.species==='cat'?(p.neuter==='yes'?1.2:1.4):(p.neuter==='yes'?1.6:1.8);}
  function special(p){return ['growth','reproduction','hospital'].includes(p.life)||n(p.age)<12;}
  function candidates(products,p){if(special(p)||(p.conditions||[]).includes('other'))return[];const needs=[...(p.conditions||[])];if(p.goal==='loss')needs.push('weight');if(!needs.length)needs.push('maintenance');return products.filter(x=>x.species===p.species&&n(p.age)>=x.minAge&&n(p.age)<x.maxAge&&(!x.minWeight||n(p.weight)>=x.minWeight)&&(!x.maxWeight||n(p.weight)<x.maxWeight)&&needs.every(k=>x.purposes.includes(k))&&['renal','urinary','allergy','lowfat'].every(k=>!x.purposes.includes(k)||p.conditions.includes(k))&&!contraErrors(x,p).length);}
  function contraErrors(x,p){const codes=(x.contra||[]).map(c=>c.code);const errors=[];if(p.conditions.includes('renal')&&codes.includes('chronic_kidney_disease'))errors.push(`${x.name}: 제조사 비권장 상황에 만성 신장질환이 포함됩니다.`);if(p.conditions.includes('lowfat')&&codes.includes('pancreatitis'))errors.push(`${x.name}: 췌장염 비권장 제품입니다. 저지방 적합성을 확인하세요.`);return errors;}
  function calculate(p,primary,secondary){const errors=[],warnings=[];if(!['dog','cat'].includes(p.species))errors.push('동물 종류를 확인하세요.');if(!within(p.weight,.1,150))errors.push('현재 체중은 0.1–150 kg 범위로 입력하세요.');if(!within(p.age,1,360)||!Number.isInteger(n(p.age)))errors.push('나이는 1–360개월의 정수로 입력하세요.');if(!within(p.bcs,1,9))errors.push('BCS를 확인하세요.');if(!within(p.meals,1,12)||!Number.isInteger(n(p.meals)))errors.push('하루 급여 횟수는 1–12회의 정수로 입력하세요.');if(!within(p.treats,0,30000))errors.push('기타 섭취 열량은 0 이상으로 입력하세요.');
    if(special(p))errors.push('첫 버전은 성체 외래 환자용입니다. 성장기·임신·수유·입원 영양 계획은 지원하지 않습니다.');
    let base=n(p.weight);if(p.goal==='loss'){if(!within(p.target,.1,150)||n(p.target)>=n(p.weight))errors.push('감량 목표 체중은 현재 체중보다 작게 직접 입력하세요.');base=n(p.target);if(n(p.bcs)<=5)warnings.push('BCS 5 이하입니다. 감량 목표의 적절성을 다시 평가하세요.');}
    const autoNeedsReview=p.conditions.length>0||p.mcs!=='normal'||p.goal==='gain'||p.activity==='high'||n(p.bcs)<=3;
    if(p.energyMode==='auto'&&autoNeedsReview)errors.push('질병·근육 감소·증량·높은 활동량·BCS 3 이하 환자는 수의사 지정 계수 또는 목표 열량을 입력하세요.');
    if(p.conditions.length>1)warnings.push('복합 질환의 식이 조건을 모두 검토하세요. 용도 일치가 임상적 적합성을 보장하지 않습니다.');
    if(p.conditions.includes('other'))warnings.push('기타 질환의 식이 요구는 자동 평가하지 않습니다. 담당 수의사가 선택한 제품의 적합성을 별도로 검토하세요.');
    if(p.conditions.includes('renal'))warnings.push('CKD 단계, 인 수치, 단백뇨·식욕·근육 상태에 맞는 신장 식이를 검토하세요. 얼리 레날과 일반 레날을 구분하세요.');
    if(p.conditions.includes('urinary'))warnings.push('결석 종류, 용해·재발 관리 목적, 신장·심장 상태 및 소변 산성화 약물 사용을 확인하세요.');
    if(p.conditions.includes('allergy'))warnings.push('식이 이상반응 관리 시 모든 추가 음식·간식·투약용 음식의 적합성을 확인하세요.');
    if(p.conditions.includes('gi')||p.conditions.includes('lowfat'))warnings.push('소화기질환의 원인과 저지방·섬유질 요구를 확인하세요. 소화기용 제품이 모두 저지방 식이는 아닙니다.');
    let factor=automaticFactor(p),total=null;
    if(p.energyMode==='factor'){if(!within(p.factor,.1,10))errors.push('수의사 지정 계수는 0.1–10 범위로 입력하세요.');factor=n(p.factor);}
    if(p.energyMode==='manual'){if(!within(p.manual,1,30000))errors.push('목표 열량은 1–30,000 kcal 범위로 입력하세요.');total=n(p.manual);}else total=rer(base)*factor;
    const food=total-n(p.treats);if(Number.isFinite(food)&&food<=0)errors.push('기타 섭취 열량은 하루 목표 열량보다 작아야 합니다.');if(n(p.treats)>total*.1)warnings.push('기타 음식이 목표 열량의 10%를 초과합니다. 영양 균형과 치료 식이 적합성을 검토하세요.');
    if(p.mixed){if(!within(p.ratio,1,99))errors.push('혼합 열량 비율은 1–99%로 입력하세요.');if(!secondary)errors.push('두 번째 제품을 선택하세요.');if(primary&&secondary&&primary.id===secondary.id)errors.push('혼합 급여는 서로 다른 두 제품을 선택하세요.');if(primary&&secondary&&primary.type===secondary.type)warnings.push('동일한 형태의 두 제품 혼합입니다. 제품별 열량을 나누어 계산합니다.');}
    const amounts=[];const selected=p.mixed?[primary,secondary]:[primary];selected.forEach((x,i)=>{if(!x){if(i===0)errors.push('사료를 선택하세요.');return;}if(x.species!==p.species)errors.push(`${x.name}: 환자의 동물 종류와 맞지 않습니다.`);if(n(p.age)<x.minAge||n(p.age)>=x.maxAge)errors.push(`${x.name}: 등록된 적용 연령 범위를 벗어납니다.`);if((x.maxWeight&&n(p.weight)>=x.maxWeight)||(x.minWeight&&n(p.weight)<x.minWeight))errors.push(`${x.name}: 등록된 체중 범위를 벗어납니다. 체구와 제품 용도를 확인하세요.`);errors.push(...contraErrors(x,p));const density=kcalPerGram(x);if(!density)errors.push(`${x.name}: 포장 열량과 단위를 확인하여 입력하세요.`);else if(!x.labelConfirmed)errors.push(`${x.name}: 실제 제품 포장 열량과 일치하는지 확인하세요.`);const required=[...p.conditions.filter(k=>k!=='other'),...(p.goal==='loss'?['weight']:[])];if(required.some(k=>!x.purposes.includes(k)))warnings.push(`${x.name}: 선택된 관리 조건을 모두 충족하는 용도로 등록되지 않았습니다. 별도 임상 검토가 필요합니다.`);if(density){const share=p.mixed?(i===0?n(p.ratio)/100:1-n(p.ratio)/100):1;const kcal=food*share;const grams=kcal/density;amounts.push({id:x.id,name:x.name,brand:x.brand,type:x.type,kcal,grams,perMeal:grams/n(p.meals),packs:x.packGrams?grams/n(x.packGrams):null,density});}});
    if(p.mixed)warnings.push('혼합 급여로 각 제품의 치료 영양 설계가 달라질 수 있으므로 혼합 적합성을 확인하세요.');
    if(Number.isFinite(total)&&total<rer(n(p.weight))&&selected.some(x=>x?.purposes.includes('maintenance')))warnings.push('현재 체중 RER보다 낮은 열량입니다. 일반 유지식으로 제한할 때 영양소 충족을 검토하세요.');
    return{ok:errors.length===0,errors:[...new Set(errors)],warnings:[...new Set(warnings)],currentRer:rer(n(p.weight)),baseWeight:base,baseRer:rer(base),factor:p.energyMode==='manual'?null:factor,total:Number.isFinite(total)?total:null,food:Number.isFinite(food)?food:null,amounts};
  }
  function validateProduct(p){if(!p||typeof p!=='object'||!['rc','hills'].includes(p.brand)||!['dog','cat'].includes(p.species)||!['dry','wet'].includes(p.type)||typeof p.name!=='string'||!p.name.trim()||p.name.length>150||typeof p.id!=='string'||p.id.length>100)throw Error('제품 형식이 올바르지 않습니다.');if(!Array.isArray(p.purposes)||!p.purposes.length||p.purposes.some(x=>!Object.hasOwn(labels,x)))throw Error('관리 목적을 확인하세요.');if(!within(p.minAge,1,360)||!within(p.maxAge,2,361)||p.minAge>=p.maxAge)throw Error('적용 연령을 확인하세요.');if(p.energy!==null&&kcalPerGram(p)===null)throw Error('열량·단위·포장 중량을 확인하세요.');if(p.labelConfirmed&&!kcalPerGram(p))throw Error('열량 없이 확인 상태를 저장할 수 없습니다.');if(p.url&&!/^https?:\/\//i.test(p.url))throw Error('자료 URL은 http 또는 https 주소여야 합니다.');if(typeof p.notes!=='string'||p.notes.length>6000||typeof p.energySource!=='string'||p.energySource.length>1000)throw Error('제품 메모 또는 출처 형식이 올바르지 않습니다.');if(p.labelConfirmed&&!p.energySource.trim())throw Error('확인한 열량의 출처를 입력하세요.');return p;}
  const api={labels,rer,n,within,kcalPerGram,automaticFactor,candidates,calculate,validateProduct};
  if(typeof module!=='undefined')module.exports=api;else root.VetEngine=api;
})(typeof window!=='undefined'?window:globalThis);
